  "code": "def next_dependency_precondition_call(service_ready: bool, blocker_active: bool, blocker_kind: str, target_action: str, blocked_reason: str) -> dict:\n    \"\"\"Return a single precondition ToolSandbox call (or abstain) based on visible state.\n\n    Runtime contract (returned dict):\n      - tool_name: '' or 'set_wifi_status'\n      - arguments: {} or {'on': True/False}\n      - should_call: bool\n      - reason: short explanation\n\n    Deterministic rules:\n      - If service_ready is True -> abstain (already ready).\n      - If target_action is empty -> abstain (unknown downstream target).\n      - If blocker_active is True:\n          - If blocker_kind indicates low-battery/power_saving/airplane -> return set_wifi_status(on=False).\n          - If blocker_kind empty/unknown -> abstain (ambiguous).\n      - If blocker_active is False and service_ready is False -> return set_wifi_status(on=True).\n\n    The function does not perform any side-effects; it merely returns the original precondition tool name and arguments.\n    \"\"\"\n    # Normalize inputs safely\n    bk = (blocker_kind or \"\").strip().lower()\n    ta = (target_action or \"\").strip().lower()\n\n    # If dependency already ready, abstain\n    if service_ready:\n        return {\"tool_name\": \"\", \"arguments\": {}, \"should_call\": False, \"reason\": \"dependency already ready\"}\n\n    # If we don't know what downstream action is, abstain\n    if not ta:\n        return {\"tool_name\": \"\", \"arguments\": {}, \"should_call\": False, \"reason\": \"unknown target action; cannot determine precondition\"}\n\n    # If an active blocker exists, prefer disabling the blocker-related feature\n    if blocker_active:\n        if not bk:\n            return {\"tool_name\": \"\", \"arguments\": {}, \"should_call\": False, \"reason\": \"unknown blocker kind; ambiguous precondition\"}\n        # Known blocker kinds that deterministically map to disabling wifi\n        if any(k in bk for k in [\"low_